pub fn get_clickhouse_root_grammar_id() -> GrammarId {
    GrammarId(2062)
}
pub fn get_clickhouse_root_grammar_table() -> RootGrammar {
    RootGrammar {
        grammar_id: get_clickhouse_root_grammar_id(),
        tables: &CLICKHOUSE_TABLES,
    }
}
pub fn get_clickhouse_root_grammar() -> RootGrammar {
    get_clickhouse_root_grammar_table()
}
